mapper.select:
SELECT id, project_id, station_id, instrument_id, batch_id, sample_index,
       sample_offset_ms, sample_time, x_raw, y_raw, z_raw,
       x_accel, y_accel, z_accel, accel_unit, quality_flag,
       source_record_key, created_at
FROM ${tableName}

    AND project_id = #{query.projectId}
    AND station_id = #{query.stationId}
    AND instrument_id = #{query.instrumentId}
    AND sample_time >= #{query.startTime}
    AND sample_time <= #{query.endTime}

ORDER BY sample_time ASC, sample_index ASC, id ASC
LIMIT #{limit}
